// Python-style value formatting (repr / str / print semantics).

function reprNumber(n) {
  if (Number.isInteger(n)) return String(n);
  return String(n);
}

function reprString(s) {
  const hasSingle = s.includes("'");
  const hasDouble = s.includes('"');
  // Python prefers single quotes, switches to double quotes when the
  // string contains a single quote but no double quote.
  const quote = hasSingle && !hasDouble ? '"' : "'";
  let out = quote;
  for (const ch of s) {
    const code = ch.codePointAt(0);
    if (ch === '\\') out += '\\\\';
    else if (ch === quote) out += '\\' + quote;
    else if (ch === '\n') out += '\\n';
    else if (ch === '\r') out += '\\r';
    else if (ch === '\t') out += '\\t';
    else if (code < 32 || code === 127) {
      out += '\\x' + code.toString(16).padStart(2, '0');
    } else {
      out += ch;
    }
  }
  return out + quote;
}

export function pyRepr(value) {
  if (value === null || value === undefined) return 'None';
  if (typeof value === 'boolean') return value ? 'True' : 'False';
  if (typeof value === 'number') return reprNumber(value);
  if (typeof value === 'string') return reprString(value);
  if (Array.isArray(value)) {
    return '[' + value.map(pyRepr).join(', ') + ']';
  }
  if (typeof value === 'object') {
    const parts = Object.entries(value).map(
      ([k, v]) => pyRepr(k) + ': ' + pyRepr(v)
    );
    return '{' + parts.join(', ') + '}';
  }
  return String(value);
}

// Mimics Python's print()/str(): strings are printed raw, everything
// else falls back to repr (dicts, lists, numbers, ...).
export function pyStr(value) {
  return typeof value === 'string' ? value : pyRepr(value);
}

// Minimal re-implementation of deepdiff's DeepDiff and extract,
// matching the observable output format of the Python library.

function isPlainDict(v) {
  return typeof v === 'object' && v !== null && !Array.isArray(v);
}

function sameKind(a, b) {
  if (Array.isArray(a) || Array.isArray(b)) return Array.isArray(a) && Array.isArray(b);
  if (isPlainDict(a) || isPlainDict(b)) return isPlainDict(a) && isPlainDict(b);
  return typeof a === typeof b;
}

function addChange(result, category, path, entry) {
  if (!(category in result)) result[category] = {};
  result[category][path] = entry;
}

function diff(t1, t2, path, result) {
  if (!sameKind(t1, t2)) {
    addChange(result, 'values_changed', path, { new_value: t2, old_value: t1 });
    return;
  }
  if (isPlainDict(t1)) {
    for (const key of Object.keys(t1)) {
      const childPath = `${path}['${key}']`;
      if (!(key in t2)) {
        addChange(result, 'dictionary_item_removed', childPath, t1[key]);
      } else {
        diff(t1[key], t2[key], childPath, result);
      }
    }
    for (const key of Object.keys(t2)) {
      if (!(key in t1)) {
        addChange(result, 'dictionary_item_added', `${path}['${key}']`, t2[key]);
      }
    }
    return;
  }
  if (Array.isArray(t1)) {
    const common = Math.min(t1.length, t2.length);
    for (let i = 0; i < common; i++) {
      diff(t1[i], t2[i], `${path}[${i}]`, result);
    }
    for (let i = common; i < t2.length; i++) {
      addChange(result, 'iterable_item_added', `${path}[${i}]`, t2[i]);
    }
    for (let i = common; i < t1.length; i++) {
      addChange(result, 'iterable_item_removed', `${path}[${i}]`, t1[i]);
    }
    return;
  }
  if (t1 !== t2) {
    addChange(result, 'values_changed', path, { new_value: t2, old_value: t1 });
  }
}

// DeepDiff category keys are emitted in alphabetical order, matching
// the printed output of the Python DeepDiff result object.
const CATEGORY_ORDER = [
  'dictionary_item_added',
  'dictionary_item_removed',
  'iterable_item_added',
  'iterable_item_removed',
  'type_changes',
  'values_changed',
];

export function deepDiff(t1, t2) {
  const collected = {};
  diff(t1, t2, 'root', collected);
  const ordered = {};
  for (const key of CATEGORY_ORDER) {
    if (key in collected) ordered[key] = collected[key];
  }
  for (const key of Object.keys(collected)) {
    if (!(key in ordered)) ordered[key] = collected[key];
  }
  return ordered;
}

// Parses paths like: root['users'][0]['name']
export function extract(obj, path) {
  if (!path.startsWith('root')) {
    throw new Error(`Path must start with 'root': ${path}`);
  }
  let current = obj;
  const rest = path.slice(4);
  const re = /\[([^\]]*)\]/g;
  let m;
  while ((m = re.exec(rest)) !== null) {
    const token = m[1];
    let key;
    if (
      (token.startsWith("'") && token.endsWith("'")) ||
      (token.startsWith('"') && token.endsWith('"'))
    ) {
      key = token.slice(1, -1);
    } else {
      key = parseInt(token, 10);
    }
    current = current[key];
  }
  return current;
}

// Minimal argparse-compatible command line parser (no dependencies).

import { pyRepr } from './pyrepr.mjs';

function basename(p) {
  const parts = String(p).split('/');
  return parts[parts.length - 1];
}

// Matches tokens that argparse treats as negative numbers (usable as
// values rather than option strings).
function looksLikeNegativeNumber(token) {
  return /^-\d+$/.test(token) || /^-\d*\.\d+$/.test(token);
}

function looksLikeOption(token) {
  return (
    token.length > 1 && token.startsWith('-') && !looksLikeNegativeNumber(token)
  );
}

// Python's int(str): optional surrounding whitespace, optional sign,
// decimal digits only.
function parsePythonInt(raw) {
  const trimmed = raw.replace(/^[ \t\n\r\f\v]+|[ \t\n\r\f\v]+$/g, '');
  if (!/^[+-]?\d+$/.test(trimmed)) return null;
  return parseInt(trimmed, 10);
}

export class ArgumentParser {
  constructor({ prog }) {
    this.prog = prog;
    this.arguments = []; // { flag, metavar, type, required }
  }

  addArgument(flag, { type = 'string', required = false, metavar } = {}) {
    this.arguments.push({
      flag,
      metavar: metavar || flag.replace(/^-+/, '').toUpperCase(),
      type,
      required,
    });
  }

  formatUsage() {
    const parts = [`usage: ${this.prog} [-h]`];
    for (const arg of this.arguments) {
      const piece = `${arg.flag} ${arg.metavar}`;
      parts.push(arg.required ? piece : `[${piece}]`);
    }
    return parts.join(' ');
  }

  formatHelp() {
    const lines = [
      this.formatUsage(),
      '',
      'options:',
      '  -h, --help  show this help message and exit',
    ];
    for (const arg of this.arguments) {
      lines.push(`  ${arg.flag} ${arg.metavar}`);
    }
    return lines.join('\n');
  }

  error(message) {
    process.stderr.write(this.formatUsage() + '\n');
    process.stderr.write(`${this.prog}: error: ${message}\n`);
    process.exit(2);
  }

  printHelp() {
    process.stdout.write(this.formatHelp() + '\n');
    process.exit(0);
  }

  parseArgs(argv) {
    const byFlag = new Map(this.arguments.map((a) => [a.flag, a]));
    const values = {};
    const extras = [];

    let i = 0;
    while (i < argv.length) {
      const token = argv[i];
      if (token === '-h' || token === '--help') {
        this.printHelp();
      }

      let flag = token;
      let inlineValue = null;
      const eq = token.indexOf('=');
      if (token.startsWith('--') && eq !== -1) {
        flag = token.slice(0, eq);
        inlineValue = token.slice(eq + 1);
      }

      const spec = byFlag.get(flag);
      if (!spec) {
        extras.push(token);
        i += 1;
        continue;
      }

      let raw;
      if (inlineValue !== null) {
        raw = inlineValue;
        i += 1;
      } else if (i + 1 < argv.length && !looksLikeOption(argv[i + 1])) {
        raw = argv[i + 1];
        i += 2;
      } else if (i + 1 < argv.length && argv[i + 1] === '-') {
        raw = argv[i + 1];
        i += 2;
      } else {
        this.error(`argument ${flag}: expected one argument`);
      }

      if (spec.type === 'int') {
        const parsed = parsePythonInt(raw);
        if (parsed === null) {
          this.error(`argument ${flag}: invalid int value: ${pyRepr(raw)}`);
        }
        values[spec.flag] = parsed;
      } else {
        values[spec.flag] = raw;
      }
    }

    const missing = this.arguments
      .filter((a) => a.required && !(a.flag in values))
      .map((a) => a.flag);
    if (missing.length > 0) {
      this.error(
        `the following arguments are required: ${missing.join(', ')}`
      );
    }

    if (extras.length > 0) {
      this.error(`unrecognized arguments: ${extras.join(' ')}`);
    }

    const result = {};
    for (const spec of this.arguments) {
      const key = spec.flag.replace(/^--?/, '');
      result[key] = values[spec.flag];
    }
    return result;
  }
}

export function progName() {
  return basename(process.argv[1] || 'test11.mjs');
}

// Entry point: mirrors /workspace/dataset/deepdiff/test11.py

import { ArgumentParser, progName } from './argparse.mjs';
import { deepDiff, extract } from './deepdiff.mjs';
import { pyStr } from './pyrepr.mjs';

const parser = new ArgumentParser({ prog: progName() });
parser.addArgument('--a', { type: 'string', required: true });
parser.addArgument('--b', { type: 'int', required: true });
const args = parser.parseArgs(process.argv.slice(2));

const obj = {
  users: [
    { name: args.a, age: args.b },
    { name: args.a + '2', age: args.b + 1 },
  ],
};

const r1 = deepDiff(obj, obj); // 比较相同对象
console.log(pyStr(r1));
const r2 = extract(obj, "root['users'][0]['name']"); // 提取特定路径的值
console.log(pyStr(r2));
const r3 = extract(obj, "root['users'][1]['age']"); // 提取另一个路径的值
console.log(pyStr(r3));
const r4 = deepDiff(obj.users[0], obj.users[1]); // 比较两个用户对象
console.log(pyStr(r4));
const r5 = extract(obj, "root['users'][0]"); // 提取整个用户对象
console.log(pyStr(r5));
const r6 = deepDiff(obj.users, []); // 比较列表和空列表
console.log(pyStr(r6));
const r7 = deepDiff(obj, { users: [] }); // 比较修改后的对象
console.log(pyStr(r7));
const r8 = extract(obj, "root['users']"); // 提取用户列表
console.log(pyStr(r8));
